 "charTable": [
  [
   "人物",
   "人物简介"
  ],
  [
   "阿木",
   "彝族青年，阿果的未婚夫，后成长为红军尖刀连连长，熟悉滇地山川民情，从私仇执念蜕变为心怀苍生的革命战士。父亲留下的那枚红绳骨哨，阿果替他收着多年，临行前才交到他手里——那是彝家人出门远行的信物，骨哨一响，便是「记得回家的路」。"
  ],
  [
   "阿细姐",
   "阿果的堂姐，比阿果年长十岁，彝寨中最会看人脸色的人。幼年与阿木、阿果一同在山涧砍柴，情同手足；最早察觉寨中来了生面孔，也最早为阿木阿果的生死担惊。第三幕末，正是她带着寨中汉子到崖底把重伤的阿木抬向渡口。见证民族隔阂消解与彝汉同心的全过程。"
  ],
  [
   "阿果",
   "彝族姑娘，阿木的未婚妻，忠贞纯粹、坚韧果敢，是坚守故土、舍身传信的底层守望者代表。母亲的凤凰帕子始终带在发带上，牺牲时浸在血泊里——那上面绣着凤凰，是她没能等到的那个人。"
  ],
  [
   "燕南云",
   "红军女战士，冷静果敢、心思缜密，专职情报侦察、敌后渗透、物资截获，战力与胆识兼备。"
  ],
  [
   "红军王团长",
   "红军主力指挥员，沉稳坚毅、果敢睿智，统筹全盘渡江作战部署，兼具军人铁血与家国温情。"
  ],
  [
   "小马哥",
   "年轻红军战士，阿木专属通信员，机敏灵动、热血纯粹，是青年红军战士群像缩影。"
  ],
  [
   "船工李老爹",
   "金沙江老牌船工，淳朴正直、明辨是非，带头打破祖辈「夜不渡皎平」的旧俗，与三十七位各族船工一道昼夜轮渡七昼夜，为三万红军将士撑起一条活路。"
  ],
  [
   "刘矬子",
   "地方乡保恶霸头目，凶狠贪婪、蛮横跋扈，长期压榨彝寨百姓，阻挠红军北上，是反动恶势力代表。"
  ],
  [
   "苟二",
   "刘矬子贴身爪牙，势利狡黠、为虎作伥，依附恶霸迫害乡民、滋扰村寨、阻拦革命队伍。"
  ],
  [
   "黄副官",
   "龙云麾下副官，奉命将一比十万比例的云南军用地图转送薛岳追剿军，途中为红军截获，成就“龙云献图”的历史佳话。"
  ]
 ],
